17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.ArrayList;
20	import java.util.Collection;
21	import java.util.List;
22	
23	import org.springframework.http.HttpHeaders;
24	import org.springframework.http.HttpStatus;
25	import org.springframework.http.ResponseEntity;
26	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
27	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
28	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
29	import org.springframework.samples.petclinic.mapper.OwnerMapper;
30	import org.springframework.samples.petclinic.mapper.PetMapper;
31	import org.springframework.samples.petclinic.mapper.VisitMapper;
32	import org.springframework.samples.petclinic.model.Owner;
33	import org.springframework.samples.petclinic.model.Pet;
34	import org.springframework.samples.petclinic.model.Visit;
35	import org.springframework.samples.petclinic.rest.api.OwnersApi;
36	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
37	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.PetDto;
39	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
42	import org.springframework.samples.petclinic.service.ClinicService;
43	import org.springframework.security.access.prepost.PreAuthorize;
44	import org.springframework.util.StringUtils;
45	import org.springframework.web.bind.annotation.CrossOrigin;
46	import org.springframework.web.bind.annotation.RequestMapping;
47	import org.springframework.web.bind.annotation.RestController;
48	import org.springframework.web.util.UriComponentsBuilder;
49	
50	import jakarta.transaction.Transactional;
51	
52	/**
53	 * @author Vitaliy Fedoriv
54	 */
55	
56	@RestController
57	@CrossOrigin(exposedHeaders = "errors, content-type")
58	@RequestMapping("/api")
59	public class OwnerRestControllerV1 implements OwnersApi {
60	
61	    private final ClinicService clinicService;
62	
63	    private final OwnerMapper ownerMapper;
64	
65	    private final PetMapper petMapper;
66	
67	    private final VisitMapper visitMapper;
68	
69	    public OwnerRestControllerV1(ClinicService clinicService,
70	                                 OwnerMapper ownerMapper,
71	                                 PetMapper petMapper,
72	                                 VisitMapper visitMapper) {
73	        this.clinicService = clinicService;
74	        this.ownerMapper = ownerMapper;
75	        this.petMapper = petMapper;
76	        this.visitMapper = visitMapper;
77	    }
78	
79	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
80	    @Override
81	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
82	        Collection<Owner> owners;
83	        if (lastName != null) {
84	            owners = this.clinicService.findOwnerByLastName(lastName);
85	        } else {
86	            owners = this.clinicService.findAllOwners();
87	        }
88	        if (owners.isEmpty()) {
89	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
90	        }
91	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
92	    }
93	
94	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
95	    @Override
96	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
97	        Owner owner = this.clinicService.findOwnerById(ownerId);
98	        if (owner == null) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
107	        validateRequiredFields(ownerFieldsDto);
108	        HttpHeaders headers = new HttpHeaders();
109	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
110	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
111	        if (!this.clinicService.findOwnerByTelephone(owner.getTelephone()).isEmpty()) {
112	            throw new DuplicateOwnerTelephoneException(owner.getTelephone());
113	        }
114	        this.clinicService.saveOwner(owner);
115	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
116	        headers.setLocation(UriComponentsBuilder.newInstance()
117	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
118	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
119	    }
120	
121	    /**
122	     * Rejects an owner payload that is missing or blank in any required field. Collects the name of
123	     * every offending field and, if there is at least one, raises a {@link MissingOwnerFieldsException}
124	     * so the client receives a 400 whose {@code errors} array lists each missing field.
125	     *
126	     * @param ownerFieldsDto the submitted owner fields
127	     */
128	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
129	        List<String> missingFields = new ArrayList<>();
130	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
131	            missingFields.add("firstName");
132	        }
133	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
134	            missingFields.add("lastName");
135	        }
136	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
137	            missingFields.add("address");
138	        }
139	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
140	            missingFields.add("city");
141	        }
142	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
143	            missingFields.add("telephone");
144	        }
145	        if (!missingFields.isEmpty()) {
146	            throw new MissingOwnerFieldsException(missingFields);
147	        }
148	    }
149	
150	    /**
151	     * Normalizes a telephone number for owner creation by stripping every non-digit character and
152	     * requiring exactly ten digits to remain. The stripped, ten-digit value is what gets stored and
153	     * returned.
154	     *
155	     * @param telephone the raw telephone value submitted by the client
156	     * @return the normalized ten-digit telephone number
157	     * @throws InvalidOwnerFieldsException if the value does not contain exactly ten digits after stripping
158	     */
159	    private String normalizeTelephone(String telephone) {
160	        String digits = telephone == null ? "" : telephone.replaceAll("\\D", "");
161	        if (digits.length() != 10) {
162	            throw new InvalidOwnerFieldsException(List.of("telephone"));
163	        }
164	        return digits;
165	    }
166	
167	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
168	    @Override
169	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
170	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
171	        if (currentOwner == null) {
172	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
173	        }
174	        currentOwner.setAddress(ownerFieldsDto.getAddress());
175	        currentOwner.setCity(ownerFieldsDto.getCity());
176	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
177	        currentOwner.setLastName(ownerFieldsDto.getLastName());
178	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
179	        this.clinicService.saveOwner(currentOwner);
180	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
181	    }
182	
183	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
184	    @Transactional
185	    @Override
186	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
187	        Owner owner = this.clinicService.findOwnerById(ownerId);
188	        if (owner == null) {
189	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
190	        }
191	        this.clinicService.deleteOwner(owner);
192	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
193	    }
194	
195	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
196	    @Override
197	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
198	        Owner owner = this.clinicService.findOwnerById(ownerId);
199	        if (owner == null) {
200	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
201	        }
202	        HttpHeaders headers = new HttpHeaders();
203	        Pet pet = petMapper.toPet(petFieldsDto);
204	        owner.setId(ownerId);
